try {
  console.log('Loading configuration from .env.test...');
  const config = load('.env.test');

  console.log('\nConfiguration loaded successfully!');
  console.log('\nList of config key names:');
  console.log('=========================');

  // Get all keys and print them sorted alphabetically
  const keys = Object.keys(config).sort();

  keys.forEach((key, index) => {
    console.log(`${index + 1}. ${key}`);
  });

  console.log(`\nTotal keys: ${keys.length}`);

  // Also print a sample of values (without showing full secrets for security)
  console.log('\nSample values (truncated for security):');
  console.log('=====================================');
  keys.forEach(key => {
    const value = config[key];
    const truncated = value.length > 30 ? value.substring(0, 30) + '...' : value;
    console.log(`${key}: ${truncated}`);
  });

} catch (error) {
  console.error('Error loading configuration:', error.message);
  process.exit(1);
}

